import{_ as e,o as t,c as a,a3 as o}from"./chunks/framework.B5WAEDB7.js";const h=JSON.parse('{"title":"jobs说明","description":"","frontmatter":{"title":"jobs说明"},"headers":[],"relativePath":"zh/00.docs/020.basic-features/060.tasks/010.jobs-intro.md","filePath":"zh/00.docs/020.basic-features/060.tasks/010.jobs-intro.md","lastUpdated":1786613910000}'),r={name:"zh/00.docs/020.basic-features/060.tasks/010.jobs-intro.md"};function n(i,s,l,c,d,p){return t(),a("div",null,[...s[0]||(s[0]=[o('<h3 id="介绍" tabindex="-1">介绍 <a class="header-anchor" href="#介绍" aria-label="Permalink to &quot;介绍&quot;">​</a></h3><p>EE框架的主进程为单进程。优点是开发效率高，但是应对计算密集型业务时，需要开发者自己学会使用 <strong>child process</strong> 或者封装渲染进程执行脚本，还需要实现通信和加密等功能；对于开发者而言难度较高。</p><p>框架提供了封装好的 <strong>任务模块</strong>，可以轻松实现开发者的需求。</p><h3 id="业务目录" tabindex="-1">业务目录 <a class="header-anchor" href="#业务目录" aria-label="Permalink to &quot;业务目录&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>./electron/jobs</span></span></code></pre></div><p>jobs 模式会 node.js 创建子进程，打包时会被排除在 bundle 之外，有单独的目录结构。</p><p><strong>重点</strong></p><ul><li>jobs 里面的代码不要引用 controller、service 中的代码，建议单独写到 jobs/ 目录中</li><li>jobs 里面不能调用 electron 的 API（electron 官方不支持），建议发送消息到主进程，让主进程去调用</li></ul>',8)])])}const _=e(r,[["render",n]]);export{h as __pageData,_ as default};
